WITH flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessions_sessions AS (SELECT id, customer_id, device, browser, started_at, country, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT customer_id, COUNT(CASE WHEN device = 'mobile' THEN 1 END) AS mobile_count, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min FROM sessions_sessions GROUP BY 1 ORDER BY mobile_count DESC;
